import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { copyFile, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

// The WASI shim is generated by Emscripten and distributed in the upstream npm release.
const upstream = 'https://registry.npmjs.org/@mlc-ai/web-runtime/-/web-runtime-0.27.0-dev0.tgz';
const integrity = 'mh4GkOlF5Ke0hxYgS6SrrnUN+OuKzcxfYLnnGv8POEK3Xhqb+E9kr0UBQ1xU1VA1UT/+z1WjGb3PxwzrzdgLVQ==';
const response = await fetch(upstream, { signal: AbortSignal.timeout(30_000) });
if (!response.ok) throw new Error(`Upstream WASI archive returned HTTP ${response.status}.`);
const bytes = Buffer.from(await response.arrayBuffer());
if (createHash('sha512').update(bytes).digest('base64') !== integrity)
  throw new Error('Upstream WASI archive integrity differs.');

const temp = await mkdtemp(join(tmpdir(), 'tvm-wasi-'));
try {
  const archive = join(temp, 'upstream.tgz');
  await writeFile(archive, bytes);
  const bundle = execFileSync('tar', ['-xOf', archive, 'package/lib/index.js'], { encoding: 'utf8' });
  const shim = bundle.match(/    function EmccWASI\(\) \{[\s\S]*?\n    \}/g);
  if (shim?.length !== 1) throw new Error('Unexpected upstream WASI shim.');
  await writeFile(new URL('../src/tvmjs_runtime_wasi.js', import.meta.url), `${shim[0]}\nexport default EmccWASI;\n`);
} finally {
  await rm(temp, { recursive: true, force: true });
}

for (const file of ['LICENSE', 'NOTICE'])
  await copyFile(new URL(`../../${file}`, import.meta.url), new URL(`../${file}`, import.meta.url));
